import{_ as o,o as i,c as a,ag as t}from"./chunks/framework.CvgP6Fyv.js";const d=JSON.parse('{"title":"Citizen Code of Conduct","description":"","frontmatter":{},"headers":[],"relativePath":"CODE_OF_CONDUCT.md","filePath":"CODE_OF_CONDUCT.md"}'),n={name:"CODE_OF_CONDUCT.md"};function r(s,e,l,c,u,h){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="citizen-code-of-conduct" tabindex="-1">Citizen Code of Conduct <a class="header-anchor" href="#citizen-code-of-conduct" aria-label="Permalink to &quot;Citizen Code of Conduct&quot;">​</a></h1><h2 id="_1-purpose" tabindex="-1">1. Purpose <a class="header-anchor" href="#_1-purpose" aria-label="Permalink to &quot;1. Purpose&quot;">​</a></h2><p>A primary goal of Api is to be inclusive to the largest number of contributors, with the most varied and diverse backgrounds possible. As such, we are committed to providing a friendly, safe and welcoming environment for all, regardless of gender, sexual orientation, ability, ethnicity, socioeconomic status, and religion (or lack thereof).</p><p>This code of conduct outlines our expectations for all those who participate in our community, as well as the consequences for unacceptable behavior.</p><p>We invite all those who participate in Api to help us create safe and positive experiences for everyone.</p><h2 id="_2-open-source-culture-tech-citizenship" tabindex="-1">2. Open [Source/Culture/Tech] Citizenship <a class="header-anchor" href="#_2-open-source-culture-tech-citizenship" aria-label="Permalink to &quot;2. Open [Source/Culture/Tech] Citizenship&quot;">​</a></h2><p>A supplemental goal of this Code of Conduct is to increase open [source/culture/tech] citizenship by encouraging participants to recognize and strengthen the relationships between our actions and their effects on our community.</p><p>Communities mirror the societies in which they exist and positive action is essential to counteract the many forms of inequality and abuses of power that exist in society.</p><p>If you see someone who is making an extra effort to ensure our community is welcoming, friendly, and encourages all participants to contribute to the fullest extent, we want to know.</p><h2 id="_3-expected-behavior" tabindex="-1">3. Expected Behavior <a class="header-anchor" href="#_3-expected-behavior" aria-label="Permalink to &quot;3. Expected Behavior&quot;">​</a></h2><p>The following behaviors are expected and requested of all community members:</p><ul><li>Participate in an authentic and active way. In doing so, you contribute to the health and longevity of this community.</li><li>Exercise consideration and respect in your speech and actions.</li><li>Attempt collaboration before conflict.</li><li>Refrain from demeaning, discriminatory, or harassing behavior and speech.</li><li>Be mindful of your surroundings and of your fellow participants. Alert community leaders if you notice a dangerous situation, someone in distress, or violations of this Code of Conduct, even if they seem inconsequential.</li><li>Remember that community event venues may be shared with members of the public; please be respectful to all patrons of these locations.</li></ul><h2 id="_4-unacceptable-behavior" tabindex="-1">4. Unacceptable Behavior <a class="header-anchor" href="#_4-unacceptable-behavior" aria-label="Permalink to &quot;4. Unacceptable Behavior&quot;">​</a></h2><p>The following behaviors are considered harassment and are unacceptable within our community:</p><ul><li>Violence, threats of violence or violent language directed against another person.</li><li>Sexist, racist, homophobic, transphobic, ableist or otherwise discriminatory jokes and language.</li><li>Posting or displaying sexually explicit or violent material.</li><li>Posting or threatening to post other people&#39;s personally identifying information (&quot;doxing&quot;).</li><li>Personal insults, particularly those related to gender, sexual orientation, race, religion, or disability.</li><li>Inappropriate photography or recording.</li><li>Inappropriate physical contact. You should have someone&#39;s consent before touching them.</li><li>Unwelcome sexual attention. This includes, sexualized comments or jokes; inappropriate touching, groping, and unwelcomed sexual advances.</li><li>Deliberate intimidation, stalking or following (online or in person).</li><li>Advocating for, or encouraging, any of the above behavior.</li><li>Sustained disruption of community events, including talks and presentations.</li></ul><h2 id="_5-weapons-policy" tabindex="-1">5. Weapons Policy <a class="header-anchor" href="#_5-weapons-policy" aria-label="Permalink to &quot;5. Weapons Policy&quot;">​</a></h2><p>No weapons will be allowed at Api events, community spaces, or in other spaces covered by the scope of this Code of Conduct. Weapons include but are not limited to guns, explosives (including fireworks), and large knives such as those used for hunting or display, as well as any other item used for the purpose of causing injury or harm to others. Anyone seen in possession of one of these items will be asked to leave immediately, and will only be allowed to return without the weapon. Community members are further expected to comply with all state and local laws on this matter.</p><h2 id="_6-consequences-of-unacceptable-behavior" tabindex="-1">6. Consequences of Unacceptable Behavior <a class="header-anchor" href="#_6-consequences-of-unacceptable-behavior" aria-label="Permalink to &quot;6. Consequences of Unacceptable Behavior&quot;">​</a></h2><p>Unacceptable behavior from any community member, including sponsors and those with decision-making authority, will not be tolerated.</p><p>Anyone asked to stop unacceptable behavior is expected to comply immediately.</p><p>If a community member engages in unacceptable behavior, the community organizers may take any action they deem appropriate, up to and including a temporary ban or permanent expulsion from the community without warning (and without refund in the case of a paid event).</p><h2 id="_7-reporting-guidelines" tabindex="-1">7. Reporting Guidelines <a class="header-anchor" href="#_7-reporting-guidelines" aria-label="Permalink to &quot;7. Reporting Guidelines&quot;">​</a></h2><p>If you are subject to or witness unacceptable behavior, or have any other concerns, please notify a community organizer as soon as possible. <a href="mailto:isoyu.com@gmail.com" target="_blank" rel="noreferrer">isoyu.com@gmail.com</a>.</p><p>Additionally, community organizers are available to help community members engage with local law enforcement or to otherwise help those experiencing unacceptable behavior feel safe. In the context of in-person events, organizers will also provide escorts as desired by the person experiencing distress.</p><h2 id="_8-addressing-grievances" tabindex="-1">8. Addressing Grievances <a class="header-anchor" href="#_8-addressing-grievances" aria-label="Permalink to &quot;8. Addressing Grievances&quot;">​</a></h2><p>If you feel you have been falsely or unfairly accused of violating this Code of Conduct, you should notify with a concise description of your grievance. Your grievance will be handled in accordance with our existing governing policies.</p><h2 id="_9-scope" tabindex="-1">9. Scope <a class="header-anchor" href="#_9-scope" aria-label="Permalink to &quot;9. Scope&quot;">​</a></h2><p>We expect all community participants (contributors, paid or otherwise; sponsors; and other guests) to abide by this Code of Conduct in all community venues--online and in-person--as well as in all one-on-one communications pertaining to community business.</p><p>This code of conduct and its related procedures also applies to unacceptable behavior occurring outside the scope of community activities when such behavior has the potential to adversely affect the safety and well-being of community members.</p><h2 id="_10-contact-info" tabindex="-1">10. Contact info <a class="header-anchor" href="#_10-contact-info" aria-label="Permalink to &quot;10. Contact info&quot;">​</a></h2><p><a href="mailto:isoyu.com@gmail.com" target="_blank" rel="noreferrer">isoyu.com@gmail.com</a></p><h2 id="_11-license-and-attribution" tabindex="-1">11. License and attribution <a class="header-anchor" href="#_11-license-and-attribution" aria-label="Permalink to &quot;11. License and attribution&quot;">​</a></h2><p>The Citizen Code of Conduct is distributed by <a href="http://stumptownsyndicate.org" target="_blank" rel="noreferrer">Stumptown Syndicate</a> under a <a href="http://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noreferrer">Creative Commons Attribution-ShareAlike license</a>.</p><p>Portions of text derived from the <a href="https://www.djangoproject.com/conduct/" target="_blank" rel="noreferrer">Django Code of Conduct</a> and the <a href="http://geekfeminism.wikia.com/wiki/Conference_anti-harassment/Policy" target="_blank" rel="noreferrer">Geek Feminism Anti-Harassment Policy</a>.</p><p><em>Revision 2.3. Posted 6 March 2017.</em></p><p><em>Revision 2.2. Posted 4 February 2016.</em></p><p><em>Revision 2.1. Posted 23 June 2014.</em></p><p><em>Revision 2.0, adopted by the <a href="http://stumptownsyndicate.org" target="_blank" rel="noreferrer">Stumptown Syndicate</a> board on 10 January 2013. Posted 17 March 2013.</em></p>',38)])])}const m=o(n,[["render",r]]);export{d as __pageData,m as default};
